const valid = n => Number.isSafeInteger(n) && n >= 0
export function lineTotal(unitCents, quantity) { if (!valid(unitCents) || !valid(quantity) || !Number.isSafeInteger(unitCents * quantity)) throw new RangeError("Safe nonnegative integer amounts required"); return unitCents * quantity }
export function balance(totalCents, payments) { if (!valid(totalCents) || !payments.every(valid)) throw new RangeError("Safe nonnegative payment amounts required"); return totalCents - payments.reduce((sum, cents) => sum + cents, 0) }

